INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-11', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會張邈與陳宮叛迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-12', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布復從東緍與陳宮將萬餘人來戰，時太祖兵少，設伏，縱奇兵擊，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-13', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '陳宮等沮其計，求救於術，勸布出戰，戰又敗，乃還固守，攻之不下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-14', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '月餘，布將宋憲、魏續等執陳宮，舉城降，生禽布、宮，皆殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-15', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '興平元年，太祖復征謙，邈弟超，與太祖將陳宮、從事中郎許汜、王楷共謀叛太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-16', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布欲降，陳宮等自以負罪深，沮其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-17', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '陳宮謂布：「宜逆擊之，以逸擊勞，無不克也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-18', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '」陳宮曰：「逆賊曹操，何等明公！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-19', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布欲令陳宮、高順守城，自將騎斷太祖糧道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-20', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '魏氏春秋曰：陳宮謂布曰：「曹公遠來，勢不能乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-21', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖塹圍之三月，上下離心，其將侯成、宋憲、魏續縛陳宮，將其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-007-22', 'p0089', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '魚氏典略曰：陳宮字公臺，東郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-010-23', 'p0089', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會張邈、陳宮以兖州反，潛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-010-24', 'p0089', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今以破李封、薛蘭，若分兵東擊陳宮，宮必不敢西顧，以其閒勒兵收熟麥，約食畜穀，一舉而布可破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-010-25', 'p0089', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '夫陳宮有智而遲，今及布氣之未復，宮謀之未定，進急攻之，布可拔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-014-26', 'p0089', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '布軍降者，言陳宮欲自將兵取東阿，又使汎嶷取范，吏民皆恐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-014-27', 'p0089', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '陳宮叛迎呂布而百城皆應，似能有為，然以君觀之，布何如人哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-014-28', 'p0089', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昱又遣別騎絕倉亭津，陳宮至，不得渡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-057-29', 'p0089', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '及陳宮、費齊皆上契天心，功德治狀，記在漢籍，有道山陰趙曄，徵士上虞王充，各洪才淵懿，學究道源，著書垂藻，駱驛百篇，釋經傳之宿疑，解當世之槃結，或上窮陰陽之奧祕，下攄人情之歸極。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a03-075-0', 'p0090', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '其督將高順諫止曰：英雄記曰「順為人不飲酒，不受饋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a03-075-1', 'p0090', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」成忿懼，乃與諸將共執陳宮、高順，率其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-001-2', 'p0090', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」呂布復為袁術使高順攻劉備，公遣夏侯惇救之，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-007-3', 'p0090', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布不知反者為誰，直牽婦，科頭袒衣，相將從溷上排壁出，詣都督高順營，直排順門入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-007-4', 'p0090', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '高順諫曰：「將軍躬殺董卓，威震夷狄，端坐顧盼，遠近自然畏服，不宜輕自出軍；如或不捷，損名非小。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-007-5', 'p0090', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '建安三年，布復叛為術，遣高順攻劉備於沛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-007-6', 'p0090', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布欲令陳宮、高順守城，自將騎斷太祖糧道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-032-7', 'p0090', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '布遣高順攻之，曹公遣夏侯惇往，不能救，為順所敗，復虜先主妻子送布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0090-a04-032-8', 'p0090', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '布由是遣中郎將高順、北地太守張遼等攻備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-067-0', 'p0091', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '度尚、張邈、王考、劉儒、胡母班、秦周、蕃嚮、王章為「八厨」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-070-1', 'p0091', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會張邈、陳宮以兖州反操，典略「宮字公臺，東郡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-073-2', 'p0091', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '會張邈迎呂布據兖州，操還擊布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-074-3', 'p0091', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-074-4', 'p0091', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '還過郯，會張邈與陳宮畔迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a03-075-5', 'p0091', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '道經陳留，太守張邈遣使迎之，相待甚厚，臨別把臂言誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-6', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '其年為卓軍所敗，走還泰山，收集勁勇得數千人，欲與張邈合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-7', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '勃海太守袁紹、陳留太守張邈、東郡太守橋瑁、英雄記曰：瑁字元偉，玄族子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-8', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會張邈與陳宮叛迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-9', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '布東奔劉備，張邈從布，使其弟超將家屬保雍丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-001-10', 'p0091', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張邈之叛也，邈劫諶母弟妻子；公謝遣之，曰：「卿老母在彼，可去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-006-11', 'p0091', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓信任尚書周毖、城門校尉伍瓊等，用其所舉韓馥、劉岱、孔伷、張咨、張邈等出宰州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-006-12', 'p0091', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '漢末名士錄曰：班字季皮，太山人，少與山陽度尚、東平張邈等八人並輕財赴義，振濟人士，世謂之八厨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-006-13', 'p0091', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '馥懷懼，從紹索去，往依張邈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-007-14', 'p0091', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '張邈字孟卓，東平壽張人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-007-15', 'p0091', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '昔漢光武謬於龐萌，近魏太祖亦蔽於張邈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-008-16', 'p0091', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '會張邈叛迎呂布，太祖還擊布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-009-17', 'p0091', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '張邈叛迎呂布，太祖家在鄄城，惇輕軍往赴，適與布會，交戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-009-18', 'p0091', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征徐州，張邈舉兖州叛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-010-19', 'p0091', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會張邈、陳宮以兖州反，潛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-014-20', 'p0091', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '張邈等叛迎呂布，郡縣響應，唯鄄城、范、東阿不動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-018-21', 'p0091', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '初平中，張邈舉義兵，韋為士，屬司馬趙寵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-024-22', 'p0091', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '」衆人皆以張邈與太祖善，柔又年少，不然其言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0091-a04-038-23', 'p0091', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-0', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '虞詡　傅爕　蓋勳　臧洪');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-1', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '臧洪字子源，廣陵射陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-2', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '邈先謂超曰：「聞弟為郡，委政臧洪，洪者何如人？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-3', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」超曰：「臧洪海內竒士，才略智數不比於超矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-4', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '超謂軍吏曰：「今日之事，唯有臧洪必來救我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-5', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '足下徼利於境外，臧洪投命於君親；吾子託身於盟主，盟主謂袁紹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-6', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '謂曰：「臧洪何相負若是！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-7', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '臧洪發舉為郡將，柰何殺之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-8', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」紹慙，使人牽出，謂曰：「汝非臧洪疇，空復爾為？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-9', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '今日寧與臧洪同日死，不與將軍同日生也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-10', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '論曰：雍丘之圍，臧洪之感憤壯矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a03-058-11', 'p0092', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '言臧洪徒守節致死，不能如包胥之存楚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-12', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臧洪字子源，廣陵射陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-13', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '邈亦素有心，會于酸棗，邈謂超曰：「聞弟為郡守，政教威恩不由己出，動任臧洪，洪者何人？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-14', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖圍張超於雍丘，超言：「唯恃臧洪，當來救吾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-15', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '足下徼利於境外，臧洪授命於君親；吾子託身於盟主，臧洪策名於長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-16', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '紹素親洪，盛施帷幔，大會諸將見洪，謂曰：「臧洪，何相負若此！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-17', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臧洪發舉為郡將，柰何殺之！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-18', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '」紹慙，左右使人牽出，謂曰：「汝非臧洪儔，空復爾為！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-19', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '今日寧與臧洪同日而死，不與將軍同日而生！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a04-007-20', 'p0092', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '陳登、臧洪並有雄氣壯節，登降年夙隕，功業未遂，洪以兵弱敵彊，烈志不立，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0092-a05-037-21', 'p0092', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '假令天長喪亂，九流渾濁，當與臧洪游於地下耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a03-070-0', 'p0093', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '而操敗於張繡，魏志，張繡在南陽降，旣而悔之，而復反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-1', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張繡降，旣而悔之，復反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-2', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公謂諸將曰：「吾降張繡等，失不便取其質，以至于此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-3', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，公將討張繡，入覲天子，時始復此制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-4', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '冬十一月，張繡率衆降，封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-001-5', 'p0093', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '迴戈東征，呂布就戮，乘轅將返，張楊殂斃，眭固伏罪，張繡稽服，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-002-6', 'p0093', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '建安初，上南征荊州，至宛，張繡降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-008-7', 'p0093', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張繡，武威祖厲人，驃騎將軍濟族子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-009-8', 'p0093', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征張繡，仁別徇旁縣，虜其男女三千餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-9', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖方東憂呂布，南拒張繡，而繡敗太祖軍於宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-10', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖大怒，出入動靜變於常，衆皆謂以失利於張繡故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-11', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '三年，太祖旣破張繡，東禽呂布，定徐州，遂與袁紹相拒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-12', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '張繡謂詡曰：「此中不可乆處，君胡不去？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-010-13', 'p0093', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '張繡在南陽，詡陰結繡，繡遣人迎詡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-017-14', 'p0093', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征張繡於安衆，圍呂布於下邳，破別將，擊眭固於射犬，攻劉備於沛，皆破之，拜討寇校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-017-15', 'p0093', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復從攻張繡於穰，禽呂布於下邳，別與史渙、曹仁攻眭固於射犬，破斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-018-16', 'p0093', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖討張繡，劉表遣兵以助繡，太祖軍不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-018-17', 'p0093', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從征張繡，先登，斬首萬計，遷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-018-18', 'p0093', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖征荊州，至宛，張繡迎降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0093-a04-020-19', 'p0093', 'sanguozhi', 'a04-020', '《三國志·魏書二十》', '隨太祖南征，為張繡所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-009-0', 'p0094', 'houhanshu', 'a03-009', '《後漢書·卷九》', '癸卯，安國將軍張楊為大司馬，韓暹為將軍，楊奉為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-009-1', 'p0094', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十一月，盜殺大司馬張楊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-017-2', 'p0094', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '彭乃潛兵度沔水，擊其將張楊於阿頭山，沔水源出武都東狼谷中，即漢水之上源也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-3', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '百官飢餓，河內太守張楊魏志曰：「楊字稚叔，雲中人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-4', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '拜胡才征東將軍，張楊為安國將軍，皆假節、開府。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-5', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '建安元年春，諸將爭權，韓暹遂攻董承，承奔張楊，楊乃使承先繕修洛宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-6', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '張楊以為己功，故因以「楊」名殿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-7', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃以張楊為大司馬，楊奉為車騎將軍，韓暹為大將軍，領司隷校尉，皆假節鉞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-8', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '操乃詣闕貢獻，稟公卿以下，因奏韓暹、張楊之罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-072-9', 'p0094', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '四年，張楊為其將楊醜所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-073-10', 'p0094', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹與故虎牙都尉劉勳，首共造兵，勳降服張楊，累有功効，而以小忿枉加酷害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-074-11', 'p0094', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '又黃巾十萬焚燒青、兖、黑山、張楊蹈藉兾城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-074-12', 'p0094', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '金鼓未震，狡敵知亡，故韓馥懷懼，謝咎歸土，張楊、黑山同時乞降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-075-13', 'p0094', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '布不安，復去從張楊於河內。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a03-075-14', 'p0094', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '紹聞，懼為患，募遣追之，皆莫敢逼，遂歸張楊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-001-15', 'p0094', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '使張楊繕治宮室，名殿曰揚安殿，八月，帝乃遷居。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-001-16', 'p0094', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '張楊將楊醜殺楊，眭固又殺醜，以其衆屬袁紹，屯射犬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-001-17', 'p0094', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '迴戈東征，呂布就戮，乘轅將返，張楊殂斃，眭固伏罪，張繡稽服，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-006-18', 'p0094', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '出箕關，下軹道，張楊以食迎道路，拜大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-006-19', 'p0094', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '浮等到，謂馥曰：「袁本初軍無斗糧，各己離散，雖有張楊、於扶羅新附，未肯為用，不足敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-007-20', 'p0094', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '呂布之捨袁紹從張楊也，過邈臨別，把手共誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-007-21', 'p0094', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '但懼秋風揚塵，伯珪馬首南向，張楊、飛燕膂力作難，北鄙將告倒縣之急，股肱奏乞歸之誠耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-008-22', 'p0094', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹與故虎牙都尉劉勳首共造兵，勳仍有効，又降伏張楊，而以小忿枉害於勳，信用讒慝，殺害有功，紹罪七也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-008-23', 'p0094', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張楊字稚叔，雲中人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-008-24', 'p0094', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '陶謙昬亂而憂死，張楊授首於臣下，皆擁據州郡，曾匹夫之不若，固無可論者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-010-25', 'p0094', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖議奉迎都許，或以山東未平，韓暹、楊奉新將天子到洛陽，北連張楊，未可卒制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-014-26', 'p0094', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昭欲詣漢獻帝，至河內，為張楊所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-014-27', 'p0094', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '時張楊為其將楊醜所殺，楊長史薛洪、河內太守繆尚城守待紹救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-019-28', 'p0094', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '」是時張楊適還河內，太祖得其書，乃引軍迎天子東詣許，以沖為司隷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0094-a04-023-29', 'p0094', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '張楊利其婦女，貪其資貨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-009-0', 'p0095', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」夏四月，黑山賊張燕率衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-058-1', 'p0095', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '魏志呂布傳曰：「布破張燕軍而求益兵，衆將士鈔掠，紹患忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-058-2', 'p0095', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '張燕，常山人，本姓褚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-071-3', 'p0095', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '賊帥常山人張燕，輕勇趫捷，故軍中號曰飛燕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-073-4', 'p0095', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '四年春，黑山賊帥張燕與續率兵十萬，三道來救瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-073-5', 'p0095', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '汝當碎首於張燕，馳驟以告急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-073-6', 'p0095', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '張燕旣為紹所敗，人衆稍散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-074-7', 'p0095', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '若舉軍東向，則黃巾可埽；還討黑山，則張燕可滅；黑山在今衞州衞縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-074-8', 'p0095', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '遂與黑山賊張燕及四營屠各、鴈門烏桓戰於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a03-075-9', 'p0095', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '有頃，布得走投袁紹，紹與布擊張燕於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-001-10', 'p0095', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏四月，黑山賊張燕率其衆十餘萬降，封為列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-006-11', 'p0095', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '雖黃巾猾亂，黑山跋扈，舉軍東向，則青州可定；還討黑山，則張燕可滅；回衆北首，則公孫必喪；震脅戎狄，則匈奴必從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-007-12', 'p0095', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '北詣袁紹，紹與布擊張燕於常山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-008-13', 'p0095', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '汝當碎首於張燕，速致輕騎，到者當起烽火於北，吾當從內出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0095-a04-008-14', 'p0095', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '張燕，常山真定人也，本姓褚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-058-0', 'p0096', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時討虜校尉公孫瓚與大司馬劉虞有隙，超乃遣洪詣虞，共謀其難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-058-1', 'p0096', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '」但懼秋風揚塵，伯珪馬首南向，伯珪，公孫瓚字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-058-2', 'p0096', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '後助公孫瓚與紹爭兾州也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-064-3', 'p0096', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '是時袁紹、曹操與公孫瓚爭兾州，紹及操聞歧至，皆自將兵數百里奉迎，歧深陳天子恩德，宜罷兵安人之道，又移書公孫瓚，為言利害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-073-4', 'p0096', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初，詔令公孫瓚討烏桓，受虞節度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-073-5', 'p0096', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '初，公孫瓚知術詐，固止虞遣兵，虞不從，瓚乃陰勸術執和，使奪其兵，自是與瓚仇怨益深。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-073-6', 'p0096', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '將行，從事代郡程緒免冑而前曰：「公孫瓚雖有過惡，而罪名未正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-073-7', 'p0096', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '公孫瓚字伯珪，遼西令支人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-8', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '今兾部強實，而韓馥庸才，可密要公孫瓚將兵南下，馥聞必駭懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-9', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '「公孫瓚乘勝來南，而諸郡應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-10', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '當今之計，莫若舉兾州以讓袁氏，必厚德將軍，公孫瓚不能復與之爭矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-11', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '其冬，公孫瓚大破黃巾，還屯槃河，爾雅有九河，鉤槃是其一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-12', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會公孫瓚師旅南馳，陸掠北境，臣即星駕席卷，與瓚交鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-13', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '四年春，擊公孫瓚，遂定幽土，事在瓚傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-14', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」曹操法令旣行，士卒精練，非公孫瓚坐受圍者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-15', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '時兾州方有北鄙之警，匪遑離局，北鄙之儆謂公孫瓚攻紹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-074-16', 'p0096', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '往歲伐鼓北征，討公孫瓚，強禦桀逆，拒圍一年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-075-17', 'p0096', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '乃各外交黨援，以相圖謀，術結公孫瓚，而紹連劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-075-18', 'p0096', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」又與公孫瓚書，云紹非袁氏子，紹聞大怒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-075-19', 'p0096', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '公孫瓚使劉備與術合謀共逼紹，紹與曹操會擊，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-090-20', 'p0096', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '建安初，兾州牧袁紹與前將軍公孫瓚相持不決，蹋頓遣使詣紹求和親，遂遣兵助擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a03-103-21', 'p0096', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」公孫瓚以為易地當之，遂徙鎮焉，乃修城積穀，以待天下之變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-001-22', 'p0096', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術與紹有隙，術求援於公孫瓚，瓚使劉備屯高唐，單經屯平原，陶謙屯發干，以逼紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-001-23', 'p0096', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '是時袁紹旣并公孫瓚，兼四州之地，衆十餘萬，將進軍攻許，諸將以為不可敵，公曰：「吾知紹之為人，志大而智小，色厲而膽薄，忌克而少威，兵多而分畫不明，將驕而政令不一，土地雖廣，糧食雖豐，適足以為吾奉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-24', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '後馥軍安平，為公孫瓚所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-25', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」紀曰：「可與公孫瓚相聞，導使來南，擊取兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-26', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會卓西入關，紹還軍延津，因馥惶遽，使陳留高幹、頴川荀諶等說馥曰：「公孫瓚乘勝來向南，而諸郡應之，袁車騎引軍東向，此其意不可知，竊為將軍危之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-27', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '英雄記曰：公孫瓚擊青州黃巾賊，大破之，還屯廣宗，改易守令，兾州長吏無不望風響應，開門受之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-28', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '曹氏法令旣行，士卒精練，非公孫瓚坐受圍者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-29', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '往歲伐鼓北征，討公孫瓚，彊禦桀逆，拒圍一年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-30', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹後用豐謀，以平公孫瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-006-31', 'p0096', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '旣與紹有隙，又與劉表不平而北連公孫瓚；紹與瓚不和而南連劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-007-32', 'p0096', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '使人於山陽界亡失文字，太祖又手書厚加慰勞布，說起迎天子，當平定天下意，并詔書購捕公孫瓚、袁術、韓暹、楊奉等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-007-33', 'p0096', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '超遣洪詣大司馬劉虞謀，值公孫瓚之難，至河間，遇幽、兾二州交兵，使命不達。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-007-34', 'p0096', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案：公孫瓚表列紹罪過云：「紹與故虎牙將軍劉勳首共造兵，勳仍有效，而以小忿枉害於勳，紹罪七也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-008-35', 'p0096', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '公孫瓚字伯珪，遼西令支人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-008-36', 'p0096', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹破走，太祖喜，顧謂輔曰：「如前歲本初送公孫瓚頭來，孤自視忽然耳，而今克之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-008-37', 'p0096', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹與公孫瓚爭兾州，燕遣將杜長等助瓚，與紹戰，為紹所敗，人衆稍散，太祖將定兾州，燕遣使求佐王師，拜平北將軍；率衆詣鄴，封安國亭侯，邑五百戶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-008-38', 'p0096', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '評曰：公孫瓚保京，坐待夷滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-011-39', 'p0096', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '且公孫瓚阻兵安忍，不早圖之，必有後悔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-011-40', 'p0096', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '得報，馳還，未至，虞已為公孫瓚所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-014-41', 'p0096', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '是時岱與袁紹、公孫瓚和親，紹令妻子居岱所，瓚亦遣從事范方將騎助岱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-014-42', 'p0096', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '夫公孫瓚，非袁紹之敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-014-43', 'p0096', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」嘉又曰：「紹方北擊公孫瓚，可因其遠征，東取呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-014-44', 'p0096', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '紹逆公孫瓚於界橋，鉅鹿太守李邵及郡冠蓋，以瓚兵彊，皆欲屬瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-017-45', 'p0096', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '紹以郃為校尉，使拒公孫瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-017-46', 'p0096', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '九州春秋曰：初，清河季雍以鄃叛袁紹而降公孫瓚，瓚遣兵衞之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-022-47', 'p0096', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '當袁紹、公孫瓚交兵，幽兾饑荒，養寡嫂孤兄子，以學行見稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-026-48', 'p0096', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '劉備之奔公孫瓚也，豫時年少，自託於備，備甚奇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-026-49', 'p0096', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '公孫瓚使豫守東州令，瓚將王門叛瓚，為袁紹將萬餘人來攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-030-50', 'p0096', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '袁紹與公孫瓚連戰不決，蹋頓遣使詣紹求和親，助紹擊瓚，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-030-51', 'p0096', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '自我王室多故，公孫瓚作難，殘夷厥土之君，以侮天慢主，是以四海之內，並執干戈以衞社稷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-032-52', 'p0096', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」年十五，母使行學，與同宗劉德然、遼西公孫瓚俱事故九江太守同郡盧植。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-032-53', 'p0096', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '為賊所破，往奔中郎將公孫瓚，瓚表為別部司馬，使為青州刺史田楷以拒兾州牧袁紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-032-54', 'p0096', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '袁紹攻公孫瓚，先主與田楷東屯齊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-036-55', 'p0096', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '本屬公孫瓚，瓚遣先主為田楷拒袁紹，雲遂隨從，為先主主騎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-036-56', 'p0096', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '雲別傳曰：雲身長八尺，姿顏雄偉，為本郡所舉，將義從吏兵詣公孫瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0096-a04-046-57', 'p0096', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '元惡旣斃，幼主東顧，俾保傅宣命，欲令諸軍振旅，然河北通謀黑山，曹操放毒東徐，劉表稱亂南荊，公孫瓚炰烋北幽，劉繇決力江滸，劉備爭盟淮隅，是以未獲承命櫜弓戢戈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a03-057-0', 'p0097', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '建寧二年，詔舉有道之士，弼與東海陳敦、玄菟公孫度俱對策，皆除郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a03-081-1', 'p0097', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '太守公孫度接以昆弟之禮，魏志曰：「公孫度字升濟，本遼東襄平人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-008-2', 'p0097', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '公孫度字升濟，本遼東襄平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-3', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '公孫度在遼東，擅留茂，不遣之官，然茂終不為屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-4', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」臣松之案此傳云公孫度聞曹公遠征，鄴無守備，則太祖定鄴後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-5', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '遼東太守公孫度畏惡欲殺之，盡收捕其家，政得脫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-6', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '天下大亂，聞公孫度令行於海外，遂與原及平原王烈等至于遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-011-7', 'p0097', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '辭公孫度長史，商賈自穢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-030-8', 'p0097', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '漢末，公孫度雄張海東，威服外夷，夫餘王尉仇台更屬遼東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a04-030-9', 'p0097', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '公孫度之雄海東也，伯固遣大加優居、主簿然人等助度擊富山賊，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0097-a05-014-10', 'p0097', 'jinshu', 'a05-014', '《晉書·卷十四》', '後漢末，公孫度自號平州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-003-0', 'p0098', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '癸巳，以大將軍曹真為大司馬，驃騎將軍司馬宣王為大將軍，遼東太守公孫淵為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-003-1', 'p0098', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，公孫淵斬送孫權所遣使張彌、許晏首，以淵為大司馬樂浪公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-003-2', 'p0098', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '遣幽州刺史毌丘儉率諸軍及鮮卑、烏丸屯遼東南界，璽書徵公孫淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-003-3', 'p0098', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '丙寅，司馬宣王圍公孫淵於襄平，大破之，傳淵首于京都，海東諸郡平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-004-4', 'p0098', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '丁丑詔曰：「太尉體道正直，盡忠三世，南擒孟達，西破蜀虜，東滅公孫淵，功蓋海內。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-008-5', 'p0098', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魏名臣奏載中領軍夏侯獻表曰：「公孫淵昔年敢違王命，廢絕計貢者，實挾兩端。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-008-6', 'p0098', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '昕等伏自惟省，螻蟻小醜，器非時用，遭值千載，被受公孫淵祖考以來光明之德，惠澤沾渥，滋潤榮華，無尺寸之功，有負乘之累；遂蒙襃獎，登名天府，並以駑蹇附龍託驥，紆青拖紫，飛騰雲梯，感恩惟報，死不擇地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-008-7', 'p0098', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '漢晉春秋曰：公孫淵自立，稱紹漢元年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-014-8', 'p0098', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '遼東太守公孫淵奪叔父位，擅自立，遣使表狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-014-9', 'p0098', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」漢晉春秋曰：公孫淵聞魏將來討，復稱臣於孫權，乞兵自救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-014-10', 'p0098', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太和末，吳遣將周賀浮海詣遼東，招誘公孫淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-021-11', 'p0098', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時聞公孫淵受孫權燕王之號，議者欲留淵計吏，遣兵討之，劭以為「昔袁尚兄弟歸淵父康，康斬送其首，是淵先世之効忠也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-024-12', 'p0098', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '初，公孫淵兄晃，為叔父恭任內侍，先淵未反，數陳其變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-026-13', 'p0098', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和末，公孫淵以遼東叛，帝欲征之而難其人，中領軍楊曁舉豫應選。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-028-14', 'p0098', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '公孫淵逆與儉戰，不利，引還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-030-15', 'p0098', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '而公孫淵仍父祖三世有遼東，天子為其絕域，委以海外之事，遂隔斷東夷，不得通於諸夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-030-16', 'p0098', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '公孫淵伏誅，玄菟庫猶有玉匣一具。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-030-17', 'p0098', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '景初二年，太尉司馬宣王率衆討公孫淵，宮遣主簿大加將數千人助軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-047-18', 'p0098', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '冬十月，魏遼東太守公孫淵遣校尉宿舒、閬中令孫綜稱藩於權，并獻貂馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-047-19', 'p0098', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '後拜宣信校尉，往救公孫淵，已為魏所破，還遷執金吾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-052-20', 'p0098', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '權以公孫淵稱藩，遣張彌、許晏至遼東拜淵為燕王，昭諫曰：「淵背魏懼討，遠來求援，非本志也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-053-21', 'p0098', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '時公孫淵降而復叛，權盛怒，欲自親征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-057-22', 'p0098', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '孫權忿公孫淵之巧詐反覆，欲親征之，瑁上疏諫曰：「臣聞聖王之御遠夷，羈縻而已，不常保有，故古者制地，謂之荒服，言慌惚無常，不可保也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0098-a04-058-23', 'p0098', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '及公孫淵背盟，權欲往征，遜上疏曰：「淵憑險恃固，拘留大使，名馬不獻，實可讎忿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-035-0', 'p0099', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '會黃巾寇青部，乃避地徐州，徐州牧陶謙接以師友之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-048-1', 'p0099', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '興平元年，前太尉曹嵩及子德從琅邪入太山，劭遣兵迎之，未到，而徐州牧陶謙素怨嵩子操數擊之，乃使輕騎追嵩、德，並殺之於郡界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-068-2', 'p0099', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '徐州刺史陶謙禮之甚厚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-070-3', 'p0099', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '興平元年，操東擊陶謙，使彧守甄城，縣名，屬濟陰郡，今濮州縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-070-4', 'p0099', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '「呂將軍來助曹使君擊陶謙，宜亟供軍實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-070-5', 'p0099', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '二年，陶謙死，操欲遂取徐州，還定呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-071-6', 'p0099', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '徐州刺史陶謙遣精兵三千，餘州郡稍有所給，謙乃上儁行車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-071-7', 'p0099', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '陶謙以儁名臣，數有戰功，可委以大事，乃與諸豪桀共推儁為太師，因移檄牧伯，同討李傕等，奉迎天子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-071-8', 'p0099', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '乃奏記於儁曰：「徐州刺史陶謙、前楊州刺史周乾、琅邪相陰德、東海相劉馗、馗音巨眉反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-071-9', 'p0099', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '軍吏皆憚入關，欲應陶謙等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-073-10', 'p0099', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '陶謙字恭祖，丹陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-073-11', 'p0099', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '吳書曰：「陶謙父，故餘姚長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-073-12', 'p0099', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '」少為諸生，仕州郡，吳書曰：「陶謙察孝廉，拜尚書郎，除舒令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-074-13', 'p0099', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '自是士林憤痛，人怨天怒，一夫奮臂，舉州同聲，故躬破於徐方，地奪於呂布，魏志曰：「陶謙為徐州牧，操初征之，下十餘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-075-14', 'p0099', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '興平元年，曹操東擊陶謙，令其將武陽人陳宮屯東郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a03-078-15', 'p0099', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '及子操起兵，不肯相隨，乃與少子疾避亂琅邪，為徐州刺史陶謙所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-16', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術與紹有隙，術求援於公孫瓚，瓚使劉備屯高唐，單經屯平原，陶謙屯發干，以逼紹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-17', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '下邳闕宣聚衆數千人，自稱天子；徐州牧陶謙與共舉兵，取泰山華、費，略任城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-18', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '秋，太祖征陶謙，下十餘城，謙守城不敢出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-19', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '興平元年春，太祖自徐州還，初，太祖父嵩去官後還譙，董卓之亂，避難琅邪，為陶謙所害，故太祖志在復讎東伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-20', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖令泰山太守應劭送家詣兖州，劭兵未至，陶謙密遣數千騎掩捕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-21', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '陶謙遣都尉張闓將騎二百衞送，闓於泰山華、費間殺嵩，取財物，因奔淮南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-22', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '太祖歸咎於陶謙，故伐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-001-23', 'p0099', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏，使荀彧、程昱守鄄城，復征陶謙，拔五城，遂略地至東海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-007-24', 'p0099', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖之征陶謙，勑家曰；「我若不還，往依孟卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-007-25', 'p0099', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '是時世荒民饑，州牧陶謙表登為典農校尉，乃巡土田之宜，盡鑿溉之利，秔稻豐積。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-008-26', 'p0099', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '徐州牧陶謙初辟別駕從事，辭疾遜遁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-008-27', 'p0099', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '陶謙昬亂而憂死，張楊授首於臣下，皆擁據州郡，曾匹夫之不若，固無可論者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-009-28', 'p0099', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征陶謙，留惇守濮陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-009-29', 'p0099', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '別攻陶謙將呂由，破之，還與大軍合彭城，大破謙軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-30', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '興平元年，太祖征陶謙，任彧留事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-31', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '布旣至，邈乃使劉翊告彧曰：「呂將軍來助曹使君擊陶謙，宜亟供其軍食。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-32', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '陶謙死，太祖欲遂取徐州，還乃定布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-33', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '且陶謙雖死，徐州未易亡也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-010-34', 'p0099', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '陶謙帥其衆軍武原，太祖不得進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-013-35', 'p0099', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '徐州刺史陶謙察朗茂才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-017-36', 'p0099', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖之征陶謙，紹使靈督三營助太祖，戰有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-018-37', 'p0099', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '黃巾起，霸從陶謙擊破之，拜騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-022-38', 'p0099', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '時陶謙病死，徐州迎備，備欲往，羣說備曰：「袁術尚彊，今東，必與之爭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-032-39', 'p0099', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公征徐州，徐州牧陶謙遣使告急於田楷，楷與先主俱救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-032-40', 'p0099', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '陶謙故將曹豹在下邳，張飛欲殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-038-41', 'p0099', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後徐州牧陶謙辟為別駕從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-046-42', 'p0099', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '許貢來領郡，岱將憲避難於許昭家，求救於陶謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-049-43', 'p0099', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '笮融者，丹楊人，初聚衆數百，往依徐州牧陶謙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-049-44', 'p0099', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '曹公攻陶謙，徐土搔動，融將男女萬口，馬三千匹，走廣陵，廣陵太守趙昱待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-049-45', 'p0099', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '先是，彭城相薛禮為陶謙所偪，屯秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-052-46', 'p0099', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」刺史陶謙舉茂才，不應，謙以為輕己，遂見拘執。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-056-47', 'p0099', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '表治行督軍校尉，特將步騎，東助徐州牧陶謙討黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0099-a04-056-48', 'p0099', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '徐州牧陶謙謂範為袁氏覘候，諷縣掠考範，範親客健兒篡取以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-009-0', 'p0100', 'houhanshu', 'a03-009', '《後漢書·卷九》', '青州黃巾擊殺兖州刺史劉岱於東平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-031-1', 'p0100', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '侍御史劉岱典考其事，岱為表陳解釋，免歸田里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-058-2', 'p0100', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '乃使詣兖州刺史劉岱、岱字公山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-072-3', 'p0100', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '侍中劉岱為兖州刺史，吳志曰：「劉岱字公山，東萊牟平人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-074-4', 'p0100', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-074-5', 'p0100', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '魏氏春秋云劉岱惡而殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a03-074-6', 'p0100', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '兖州刺史劉岱與其書，道『卓無道，天下所共攻，死在旦暮，不足為憂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-001-7', 'p0100', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」兖州刺史劉岱、岱，劉繇之兄，事見吳志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-001-8', 'p0100', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉岱與橋瑁相惡，岱殺瑁，以王肱領東郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-001-9', 'p0100', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉岱欲擊之，鮑信諫曰：「今賊衆百萬，百姓皆震恐，士卒無鬬志，不可敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-001-10', 'p0100', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-006-11', 'p0100', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓信任尚書周毖、城門校尉伍瓊等，用其所舉韓馥、劉岱、孔伷、張咨、張邈等出宰州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-006-12', 'p0100', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太祖遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-007-13', 'p0100', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '臣松之案：于時此盟止有劉岱等五人而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-012-14', 'p0100', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '會黃巾大衆入州界，劉岱欲與戰，信止之，岱不從，遂敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-014-15', 'p0100', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '初平中，兖州刺史劉岱辟昱，昱不應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-032-16', 'p0100', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '東海昌霸反，郡縣多叛曹公為先主，衆數萬人，遣孫乾與袁紹連和，曹公遣劉岱、王忠擊之，不克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0100-a04-038-17', 'p0100', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-008-full-0', 'p0101', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '三月，幽州牧劉虞購斬漁陽賊張純。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-008-full-1', 'p0101', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '太尉馬日磾免，幽州牧劉虞為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-008-2', 'p0101', 'houhanshu', 'a03-008', '《後漢書·卷八》', '三月，幽州牧劉虞購斬漁陽賊張純。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-008-3', 'p0101', 'houhanshu', 'a03-008', '《後漢書·卷八》', '太尉馬日磾免，幽州牧劉虞為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-009-4', 'p0101', 'houhanshu', 'a03-009', '《後漢書·卷九》', '乙酉，以太尉劉虞為大司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-058-5', 'p0101', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '勳時與宗正劉虞、佐軍校尉袁紹同典禁兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-058-6', 'p0101', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時討虜校尉公孫瓚與大司馬劉虞有隙，超乃遣洪詣虞，共謀其難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-7', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '劉虞字伯安，東海郯人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-8', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '瓚志埽滅烏桓，而劉虞欲以恩信招降，由是與虞相忤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-9', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '瓚旣諫劉虞遣兵就袁術，而懼術知怨之，乃使從弟越將千餘騎詣術自結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-10', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '是歲，瓚破禽劉虞，盡有幽州之地，猛志益盛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-11', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '劉虞從事漁陽鮮于輔等，合率州兵，欲共報瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-073-12', 'p0101', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '劉虞守道慕名，以忠厚自牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-075-13', 'p0101', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '太僕黃琬為豫州牧，宗正劉虞為幽州牧，皆以本秩居職。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-075-14', 'p0101', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '紹議欲立劉虞為帝，術好放縱，憚立長君，託以公義不肯同，積此釁隙遂成。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-089-15', 'p0101', 'houhanshu', 'a03-089', '《後漢書·卷八十九》', '靈帝詔發南匈奴兵，配幽州牧劉虞討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-090-16', 'p0101', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '五年，以劉虞為幽州牧，虞購募斬純首，北州乃定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-103-17', 'p0101', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '初，瓚破黃巾，殺劉虞，乘勝南下，侵據齊地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a03-114-18', 'p0101', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '」臣昭案：劉虞為大司馬，而與太尉並置焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-001-19', 'p0101', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁紹與韓馥謀立幽州牧劉虞為帝，太祖拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-001-20', 'p0101', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '獻帝起居注曰：公上言「大將軍鄴侯袁紹前與兾州牧韓馥立故大司馬劉虞，刻作金璽，遣故任長畢瑜詣虞，為說命錄之數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-006-21', 'p0101', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹自號車騎將軍，主盟，與兾州牧韓馥立幽州牧劉虞為帝，遣使奉章詣虞，虞不敢受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-006-22', 'p0101', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '幽州牧劉虞宿有德望，紹等欲立之以安當時，使人報術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-007-23', 'p0101', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '超遣洪詣大司馬劉虞謀，值公孫瓚之難，至河間，遇幽、兾二州交兵，使命不達。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-008-24', 'p0101', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '朝議以宗正東海劉伯安旣有德義，昔為幽州刺史，恩信流著，戎狄附之，若使鎮撫，可不勞衆而定，乃以劉虞為幽州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-008-25', 'p0101', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '魏氏春秋曰：初，劉虞和輯戎狄，瓚以胡夷難禦，當因不賔而討之，今加財賞，必益輕漢，效一時之名，非乆長深慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-011-26', 'p0101', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '幽州牧劉虞歎曰：「賊臣作亂，朝廷播蕩，四海俄然，莫有固志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-011-27', 'p0101', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '瓚聞之大怒，購求獲疇，謂曰：「汝何自哭劉虞墓，而不送章報於我也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-030-28', 'p0101', 'sanguozhi', 'a04-030', '《三國志·魏書三十》', '靈帝末，以劉虞為幽州牧，募胡斬純首，北州乃定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0101-a04-031-29', 'p0101', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '出為監軍使者，領益州牧，封陽城侯，當收儉治罪；續漢書曰：是時用劉虞為幽州，劉焉為益州，劉表為荊州，賈琮為兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-009-0', 'p0102', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅攻劉表於襄陽，堅戰歿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-009-1', 'p0102', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月，曹操南征劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-009-2', 'p0102', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是月，劉表卒，少子琮立，琮以荊州降操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-056-3', 'p0102', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '同郡劉表時年十七，從暢受學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-056-4', 'p0102', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '後許汜與劉備並在荊州牧劉表坐，備共論天下人，汜曰：「陳元龍淮海之士，豪氣不除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-064-5', 'p0102', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歧雖迫大命，猶志報國家，欲自乘牛車，南說劉表，可使其身自將兵來衞朝廷，與將軍并心同力，共獎王室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-064-6', 'p0102', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歧至，劉表即遣兵詣洛陽助修宮室，軍資委輸，前後不絕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-066-7', 'p0102', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '長安之亂，容於荊州，劉表厚禮焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-067-8', 'p0102', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '張儉、岑晊、劉表、陳翔、孔昱、苑康、檀𢾭、翟超為「八及」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-067-9', 'p0102', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '以儉及檀彬、褚鳳、張肅、薛蘭、馮禧、魏玄、徐乾為「八俊」，田林、張隱、劉表、薛郁、王訪、劉祇、宣靖、公緒恭為「八顧」，公緒，姓也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-067-10', 'p0102', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '陳蕃、竇武、王暢、劉表、度尚、郭林宗別有傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-069-11', 'p0102', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '至建安中，荊州牧劉表聞而辟焉，以為從事，使還竇姓，以事列上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-12', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '是時荊州牧劉表不供職貢，多行僭偽，遂乃郊祀天地，擬斥乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-13', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '融上疏曰：「竊聞領荊州牧劉表桀逆放恣，所為不軌，至乃郊祭天地，擬儀社稷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-14', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」前以露袁術之罪，今復下劉表之事，是使跛牂欲闚高岸，天險可得而登也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-15', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '六年，操以紹新破，未能為患，但欲留兵衞之，自欲南征劉表，以計問彧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-16', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '復若南征劉表，委弃兖、豫，飢軍深入，踰越江、沔，沔即漢水也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-070-17', 'p0102', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '操將伐劉表，問彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-18', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '先是荊州牧劉表表焉僭擬乘輿器服，韙以此遂屯兵朐䏰備表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-19', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '劉表上術為南陽太守，術又表堅領豫州刺史，使率荊、豫之卒，擊破董卓於陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-20', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '乃各外交黨援，以相圖謀，術結公孫瓚，而紹連劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-21', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '初平三年，術遣孫堅擊劉表於襄陽，堅戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-075-22', 'p0102', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '曹操毒被於東徐，劉表僭亂於南荊，公孫叛逆於朔北，正禮阻兵，劉繇也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-080b-23', 'p0102', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '顧此人素有虛名，遠近將謂孤不能容之，今送與劉表，視當何如。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-080b-24', 'p0102', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '劉表及荊州士大夫先服其才名，甚賔禮之，文章言議，非衡不定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-083-25', 'p0102', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '荊州刺史劉表數延請，不能屈，乃就候之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-102-26', 'p0102', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '荊州分也，時荊州牧劉表據荊州，益州從事周羣以為荊州牧將死而失土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-103-27', 'p0102', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」言自中興以來，荊州無破亂，及劉表為牧，民又豐樂，至此逮八九年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-103-28', 'p0102', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '當始衰者，謂劉表妻當死，諸將並零落也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-105-29', 'p0102', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '』時天下尚亂，豪桀並爭：曹操事二袁於河北；孫吳創基於江外；劉表阻亂衆於襄陽，南招零、桂，北割漢川，又以黃祖為爪牙，而祖與孫氏為深讎，兵革歲交。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a03-118-30', 'p0102', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '故焉牧益土，造帝服於岷、峨；袁紹取兾，下制書於燕、朔；劉表荊南，郊天祀地；魏祖據兖，遂構皇業：漢之殄滅，禍源乎此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-31', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '荊州牧劉表斷術糧道，術引軍入陳留，屯封丘，黑山餘賊及於夫羅等佐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-32', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏五月，劉表遣兵救繡，以絕軍後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-33', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '備聞公自行，走奔劉表，都等皆散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-34', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」八月，公征劉表，軍西平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-35', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '今深入征之，劉備必說劉表以襲許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-36', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '乃論荊州服從之功，侯者十五人，以劉表大將文聘為江夏太守，使統本兵，引用荊州名士韓嵩、鄧義等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-37', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉表見紹彊，陰與紹通，儁謂表曰：「曹公，天下之雄也，必能興霸道，繼桓、文之功者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-38', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '又劉表自以為宗室，包藏姧心，乍前乍却，以觀世事，據有當州，孤復定之，遂平天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-001-39', 'p0102', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉表背誕，不供貢職，王師首路，威風先逝，百城八郡，交臂屈膝，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-40', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '魏氏春秋載劉表遺譚書曰：「天篤降害，禍難殷流，尊公殂殞，四海悼心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-41', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '旣與紹有隙，又與劉表不平而北連公孫瓚；紹與瓚不和而南連劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-42', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '劉表字景升，山陽高平人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-43', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '司馬彪戰略曰：劉表之初為荊州也，江南宗賊盛，袁術屯魯陽，盡有南陽之衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-44', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」言自中平以來，荊州獨全，及劉表為牧，民又豐樂，至建安八年九年當始衰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-45', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '始衰者，謂劉表妻死，諸將並零落也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-46', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」華谷去州數百里，即遣馬吏驗視，而劉表果死，縣乃出之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-47', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '越知進必敗，求出為汝陽令，佐劉表平定境內，表得以彊大。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-48', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '黃巾起，嵩避難南方，劉表逼以為別駕，轉從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-49', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '為劉表別駕，奉章詣許，見太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-006-50', 'p0102', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹、劉表咸有威容、器觀，知名當世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-007-51', 'p0102', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '後許汜與劉備並在荊州牧劉表坐，表與備共論天下人，汜曰：「陳元龍湖海之士，豪氣不除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-007-52', 'p0102', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '魏氏春秋橫內劉表等數人，皆非事實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-008-53', 'p0102', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '繡領其衆，屯宛，與劉表合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-009-54', 'p0102', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '別征劉表，破表別將於舞陽、陰葉、堵陽、博望，有功，遷厲鋒將軍，封國明亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-55', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」衡南見劉表，表甚禮之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-56', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '今送與劉表，視卒當何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-57', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '傅子曰：衡辯於言而剋于論，見荊州牧劉表日，所以自結於表者甚至，表恱之以為上賔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-58', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '衡以交絕於劉表，智窮於黃祖，身死名滅，為天下笑者，譖之者有形也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-59', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '六年，太祖就穀東平之安民，糧少，不足與河北相支，欲因紹新破，以其間擊討劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-60', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '一旦生變，雖有善守者，轉相脅為非，則袁尚得寬其死，而袁譚懷貳，劉表遂保江、漢之閒，天下未易圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-61', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '及紹破敗，臣糧亦盡，以為河北未易圖也，欲南討劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-62', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖將伐劉表，問彧策安出，彧曰：「今華夏已平，南土知困矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-63', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸言於太祖曰：「繡與劉表相恃為彊，然繡以遊軍仰食於表，表不能供也，勢必離。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-64', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '明年，太祖方征劉表，譚、尚爭兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-65', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸曰：「天下方有事，而劉表坐保江、漢之閒，其無四方志可知矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-66', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '傅子曰：詡南見劉表，表以客禮待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-010-67', 'p0102', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '將此旣新平江、漢，威懾揚、越，資劉表水戰之具，藉荊楚檝櫂之手，實震蕩之良會，廓定之大機。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-012-68', 'p0102', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '會天下義兵起，子伯亦合衆與劉表相依。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-012-69', 'p0102', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '將避亂荊州，未至，聞劉表政令不明，遂往魯陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-012-70', 'p0102', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '今袁紹、劉表，雖士民衆彊，皆無經遠之慮，未有樹基建本者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-014-71', 'p0102', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '不如南向荊州若征劉表者，以待其一變成而後擊之，可一舉定也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-014-72', 'p0102', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖將征袁尚及三郡烏丸，諸下多懼劉表使劉備襲許以討太祖，嘉曰：「公雖威震天下，胡恃其遠，必不設備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-014-73', 'p0102', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '曄進曰：「明公以步卒五千，將誅董卓，北破袁紹，南征劉表，九州百郡，十并其八，威震天下，勢慴海外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-016-74', 'p0102', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '張晟寇殽、澠閒，南通劉表，固等因之，吾恐其為害深。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-017-75', 'p0102', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '今天子在許，公遠北征，若劉表遣劉備襲許，據之以號令四方，公之勢去矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-76', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉表使劉備北侵，至葉，太祖遣典從夏侯惇拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-77', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖討張繡，劉表遣兵以助繡，太祖軍不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-78', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '紹遣使拜通征南將軍，劉表亦陰招之，通皆拒焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-79', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '文聘字仲業，南陽宛人也，為劉表大將，使禦北方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-018-80', 'p0102', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '岐為劉表陳其本末，由是益禮賔碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-019-81', 'p0102', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '摯虞文章志曰：劉季緒名脩，劉表子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-021-82', 'p0102', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '劉表雍容荊楚，坐觀時變，自以為西伯可規。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-021-83', 'p0102', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '太祖征袁紹，而劉表為紹援，關中諸將又中立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-021-84', 'p0102', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」廙兄望之，有名於世，荊州牧劉表辟為從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-021-85', 'p0102', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '廙懼，奔揚州，廙別傳載廙道路為牋謝劉表曰：「考匊過蒙分遇榮授之顯，未有管、狐、桓、文之烈，孤德隕命，精誠不遂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-022-86', 'p0102', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '會堅擊劉表戰死，階冒難詣表乞堅喪，表義而與之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-022-87', 'p0102', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '乆之，劉表辟為從事祭酒，欲妻以妻妹蔡氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-023-88', 'p0102', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '荊州劉表無他遠志，愛人樂士，土地險阻，山夷民弱，易依倚也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-023-89', 'p0102', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '襲避亂荊州，劉表待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-023-90', 'p0102', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '九州春秋曰：建安六年，劉表攻西鄂，西鄂長杜子緒帥縣男女嬰城而守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-023-91', 'p0102', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '避亂荊州，劉表待以賔禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-024-92', 'p0102', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '荊州牧劉表禮辟，遂遁逃，南居孱陵界，所在見敬愛，而表深恨之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-028-93', 'p0102', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '博物記曰：初，王粲與族兄凱俱避地荊州，劉表欲以女妻粲，而嫌其形陋而用率，以凱有風貌，乃以妻凱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-028-94', 'p0102', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '凱生業，業即劉表外孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-029-95', 'p0102', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '荊州牧劉表令與孟曜為漢主合雅樂，樂備，表欲庭觀之，夔諫曰：「今將軍號為天子合樂，而庭作之，無乃不可乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-96', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '出為監軍使者，領益州牧，封陽城侯，當收儉治罪；續漢書曰：是時用劉虞為幽州，劉焉為益州，劉表為荊州，賈琮為兾州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-97', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '臣松之案：靈帝崩後，義軍起，孫堅殺荊州刺史王叡，然後劉表為荊州，不與焉同時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-98', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '荊州牧劉表表上焉有似子夏在西河疑聖人之論。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-99', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '州大吏趙韙等貪璋溫仁，共上璋為益州刺史，詔書因以為監軍使者，領益州牧，以韙為征東中郎將，率衆擊劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-031-100', 'p0102', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '張松、法正，雖有君臣之義不正，然固已委名附質，進不顯陳事勢，若韓嵩、劉先之說劉表，退不告絕奔亡，若陳平、韓信之去項羽，而兩端攜貳，為謀不忠，罪之次也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-101', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公遣曹仁將兵擊先主，先主還紹軍，陰欲離紹，乃說紹南連荊州牧劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-102', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣麋笁、孫乾與劉表相聞，表自郊迎，以上賔禮待之，益其兵，使屯新野。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-103', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」　世語曰：備屯樊城，劉表禮焉，憚其為人，不甚信用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-104', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣諸葛亮自結於孫權，江表傳曰：孫權遣魯肅弔劉表二子，并令與備相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-105', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉表吏士見從北軍，多叛來投備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-032-106', 'p0102', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '三輔亂，戩客荊州，劉表以為賔客。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-035-107', 'p0102', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '玄素與荊州牧劉表有舊，往依之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-035-108', 'p0102', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '獻帝春秋曰：初，豫章太守周術病卒，劉表上諸葛玄為豫章太守，治南昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-035-109', 'p0102', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '是時曹公方定河北，亮知荊州次當受敵，而劉表性緩，不曉軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-035-110', 'p0102', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '劉表長子琦，亦深器亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-036-111', 'p0102', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主背曹公依袁紹、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-036-112', 'p0102', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '荊州牧劉表以為中郎將，與表從子磐共守長沙攸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-038-113', 'p0102', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '荊州牧劉表及儒者宋忠咸聞其名，遺書與商切致殷勤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-038-114', 'p0102', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主將適荊州，遣笁先與劉表相聞，以笁為左將軍從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-038-115', 'p0102', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主之背曹公，遣乾自結袁紹，將適荊州，乾又與麋笁俱使劉表，皆如意指。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-038-116', 'p0102', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '少依邑人鎮南將軍劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-039-117', 'p0102', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '劉表亦素不善祥，拘巴，欲殺之，數遣祥故所親信人密詐謂巴曰：「劉牧欲相危害，可相隨逃之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-039-118', 'p0102', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」荊州牧劉表連辟，及舉茂才，皆不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-040-119', 'p0102', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '荊州牧劉表使歷諸郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-041-120', 'p0102', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '篤卒，荊州牧劉表令峻攝其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-041-121', 'p0102', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '荊州牧劉表以為臨沮長。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-042-122', 'p0102', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '明年秋，劉表卒，曹公平荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-123', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」卓曰：「然，但殺二袁、劉表、孫堅，天下自服從孤耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-124', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '初平三年，術使堅征荊州，擊劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-125', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '又云：劉表將呂公將兵緣山向堅，堅輕騎尋山討公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-126', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '元惡旣斃，幼主東顧，俾保傅宣命，欲令諸軍振旅，然河北通謀黑山，曹操放毒東徐，劉表稱亂南荊，公孫瓚炰烋北幽，劉繇決力江滸，劉備爭盟淮隅，是以未獲承命櫜弓戢戈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-127', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：策被詔勑，與司空曹公、衞將軍董承、益州牧劉璋等并力討袁術、劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-128', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '至沂，築壘自守，告急於劉表，求救於黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-129', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時劉表遣從子虎、南陽韓晞將長矛五千，來為黃祖前鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-130', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '劉表遣將助祖，並來趣臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-046-131', 'p0102', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '黃祖始被策破，魂氣未反，且劉表君臣本無兼并之志，雖在上流，何辦規擬吳會？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-047-132', 'p0102', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '荊州牧劉表死，魯肅乞奉命弔表二子，且以觀變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-049-133', 'p0102', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '殺太守朱皓，獻帝春秋曰：是歲，繇屯彭澤，又使融助皓討劉表所用太守諸葛玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-049-134', 'p0102', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '劉表從子磐，驍勇，數為寇於艾、西安諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-049-135', 'p0102', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '朱符死後，漢遣張津為交州刺史，津後又為其將區景所殺，而荊州牧劉表遣零陵賴恭代津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-049-136', 'p0102', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '漢聞張津死，賜燮璽書曰：「交州絕域，南帶江海，上恩不宣，下義壅隔，知逆賊劉表又遣賴恭闚看南土，今以燮為綏南中郎將，董督七郡，領交阯太守如故。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-052-137', 'p0102', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '劉表所置蒼梧太守吳巨陰懷異心，外附內違。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-053-138', 'p0102', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '次得南陽張津，與荊州牧劉表為隙，兵弱敵彊，歲歲興軍，諸將厭患，去留自在。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-054-139', 'p0102', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今操得荊州，掩有其地，劉表治水軍，蒙衝鬬艦，乃以千數，操悉浮以沿江，兼有步兵，水陸俱下，此為長江之險，已與我共之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-054-140', 'p0102', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」權曰：「老賊欲廢漢自立乆矣，徒忌二袁、呂布、劉表與孤耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-054-141', 'p0102', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '因其多務，勦除黃祖，進伐劉表，竟長江所極，據而有之，然後建號帝王以圖天下，此高帝之業也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-054-142', 'p0102', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '孫盛曰：吳書及江表傳，魯肅一見孫權便說拒曹公而論帝王之略，劉表之死也，又請使觀變，無緣方復激說勸迎曹公也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-055-143', 'p0102', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '止不攻劫，頗讀諸子，乃往依劉表，因居南陽，不見進用，後轉託黃祖，祖又以凡人畜之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-055-144', 'p0102', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '吳書曰：寧將僮客八百人就劉表。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-055-145', 'p0102', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '寧已觀劉表，慮旣不遠，兒子又劣，非能承業傳基者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-055-146', 'p0102', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉表在荊州，民數被寇，自璋在事，寇不入境。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-059-147', 'p0102', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '臣松之以為袁紹、劉表謂尚、琮為賢，本有傳後之意，異於孫權旣以立和而復寵霸，坐生亂階，自構家禍，方之袁、劉，昏悖甚矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-059-148', 'p0102', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '近袁紹、劉表各有國土，土地非狹，人衆非弱，以適庶不分，遂滅其宗祀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-061-149', 'p0102', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '年未三十，荊州牧劉表辟為部江夏從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a04-063-150', 'p0102', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '明年戊子，荊州劉表亦身死國亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a05-012-151', 'p0102', 'jinshu', 'a05-012', '《晉書·卷十二》', '圖緯舊說，及漢末劉表為荊州牧，命武陵太守劉叡集天文衆占，名荊州占。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0102-a05-036-full-152', 'p0102', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '梁鵠奔劉表，魏武帝破荊州，募求鵠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a03-080b-0', 'p0103', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '後復侮慢於表，表恥不能容，以江夏太守黃祖性急，故送衡與之，祖亦善待焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a03-080b-1', 'p0103', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '後黃祖在蒙衝舩上，釋名曰：「外狹而長曰蒙衝，以衝突敵船。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a03-105-2', 'p0103', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '』時天下尚亂，豪桀並爭：曹操事二袁於河北；孫吳創基於江外；劉表阻亂衆於襄陽，南招零、桂，北割漢川，又以黃祖為爪牙，而祖與孫氏為深讎，兵革歲交。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-010-3', 'p0103', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '將軍黃祖屯夏口，祖子射與衡善，隨到夏口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-010-4', 'p0103', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '衡以交絕於劉表，智窮於黃祖，身死名滅，為天下笑者，譖之者有形也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-035-5', 'p0103', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '會黃祖死，得出，遂為江夏太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-6', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '表遣黃祖逆於樊、鄧之間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-7', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '典略曰；堅悉其衆攻表，表閉門，夜遣將黃祖潛出發兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-8', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '先君與袁氏共破董卓，功業未遂，卒為黃祖所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-9', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時策西討黃祖，行及石城，聞勳輕身詣海昏，便分遣從兄賁、輔率八千人於彭澤待勳，自與周瑜率二萬人步襲皖城，即克之，得術百工及鼓吹部曲三萬餘人，并術、勳妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-10', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '至沂，築壘自守，告急於劉表，求救於黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-11', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '策收得勳兵二千餘人，船千艘，遂前進夏口攻黃祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-12', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '時劉表遣從子虎、南陽韓晞將長矛五千，來為黃祖前鋒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-13', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '吳錄載策表曰：「臣討黃祖，以十二月八日到祖所屯沙羨縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-14', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '孫策雖威行江外，略有六郡，然黃祖乘其上流，陳登間其心腹，且深險彊宗未盡歸復，曹、袁虎爭，勢傾山海，策豈暇遠師汝、潁，而遷帝於吳、越哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-046-15', 'p0103', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '黃祖始被策破，魂氣未反，且劉表君臣本無兼并之志，雖在上流，何辦規擬吳會？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-047-16', 'p0103', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '勳破，進討黃祖於沙羡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0103-a04-047-17', 'p0103', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '八年，權西伐黃祖，破其舟軍，惟城未克，而山寇復動。');
